(4643611, 669264, 71619, '<td valign="top">I think you''ve framed this shot well, I enjoy the way the lines surround the blank space in the top right.</td>', 'I think you''ve framed this shot well, I enjoy the way the lines surround the blank space in the top right.', '2008-04-16 11:50:05.000000', NULL, 1),
(4643612, 668514, 71619, '<td valign="top">Great title, and I like the way you have included some expression in the image (the motion of the hand) rather than simply relying on the effects to carry the meaning.</td>', 'Great title, and I like the way you have included some expression in the image (the motion of the hand) rather than simply relying on the effects to carry the meaning.', '2008-04-16 11:50:53.000000', NULL, 1),
(4643614, 667441, 71619, '<td valign="top">How very ominous! I think the perspective you''ve chosen works really well here.</td>', 'How very ominous! I think the perspective you''ve chosen works really well here.', '2008-04-16 11:51:48.000000', NULL, 1),
(4643620, 669806, 71619, '<td valign="top">Argh! Very harrowing shot, I think you''ve achieved the effect you desired :)</td>', 'Argh! Very harrowing shot, I think you''ve achieved the effect you desired :)', '2008-04-16 11:54:14.000000', NULL, 1),
(4643623, 668118, 71619, '<td valign="top">I like this concept and the way you''ve carried it out. I would perhaps like to see more sharpening/emphasis on the top right of the clock face, particularly the seconds themselves, rather than the darker bottom left which is where I feel the emphasis is now. Great sense of movement though.</td>', 'I like this concept and the way you''ve carried it out. I would perhaps like to see more sharpening/emphasis on the top right of the clock face, particularly the seconds themselves, rather than the darker bottom left which is where I feel the emphasis is now. Great sense of movement though.', '2008-04-16 11:56:41.000000', NULL, 1),
(4643625, 668986, 71619, '<td valign="top">I''ve never seen a turtle look like a hallowe''en pumpkin before! How sinister. I like this image a lot, particularly the way the face of the beast is defined against the more blurred background.</td>', 'I''ve never seen a turtle look like a hallowe''en pumpkin before! How sinister. I like this image a lot, particularly the way the face of the beast is defined against the more blurred background.', '2008-04-16 11:59:34.000000', NULL, 1),
(4643628, 668404, 71619, '<td valign="top">Wonderful textures, especially in the bottom left. They look like they''re hiding something :)</td>', 'Wonderful textures, especially in the bottom left. They look like they''re hiding something :)', '2008-04-16 12:02:14.000000', NULL, 1),
