(4650099, 669282, 62249, '<td valign="top">I like the colors in this quite well. Too bad image is so narrow.</td>', 'I like the colors in this quite well. Too bad image is so narrow.', '2008-04-20 19:09:41.000000', NULL, 1),
(4650101, 669753, 62249, '<td valign="top">Needs more contrast. Composition is unremarkable, although textures in the hedge are interesting.</td>', 'Needs more contrast. Composition is unremarkable, although textures in the hedge are interesting.', '2008-04-20 19:10:27.000000', NULL, 1),
(4650102, 668491, 62249, '<td valign="top">I''d like this better cropped as a vertical. The dress and pink area on the right don''t add much to the shot, so try cropping just to the right of the pink shoe. The show and toenails look great.</td>', 'I''d like this better cropped as a vertical. The dress and pink area on the right don''t add much to the shot, so try cropping just to the right of the pink shoe. The show and toenails look great.', '2008-04-20 19:11:48.000000', NULL, 1),
(4650108, 669926, 62249, '<td valign="top">Try cropping this as a vertical, eliminating the right half of the photo and filling more of the frame with the bird and its reflection.</td>', 'Try cropping this as a vertical, eliminating the right half of the photo and filling more of the frame with the bird and its reflection.', '2008-04-20 19:14:41.000000', NULL, 1),
(4650109, 669618, 43774, '<td valign="top">Very clear and sharp, love the blues and purples. My only nit-pick is that it''s a bit too centered. I''d crop some off the left.</td>', 'Very clear and sharp, love the blues and purples. My only nit-pick is that it''s a bit too centered. I''d crop some off the left.', '2008-04-20 19:15:42.000000', NULL, 1),
(4650111, 669472, 43774, '<td valign="top">Love the diagonal composition. The shadow adds a nice 3-dimensional element to this, it''s almost like the leaf''s aura. Lovely! And I really like that you did not make it B&amp;W. The tinge of green is perfect.</td>', 'Love the diagonal composition. The shadow adds a nice 3-dimensional element to this, it''s almost like the leaf''s aura. Lovely! And I really like that you did not make it B&W. The tinge of green is perfect.', '2008-04-20 19:16:34.000000', NULL, 1),
(4650114, 669779, 62249, '<td valign="top">Too washed out along the bottom, but the upper petals and blue glow are nice.</td>', 'Too washed out along the bottom, but the upper petals and blue glow are nice.', '2008-04-20 19:17:45.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4650118, 667590, 62249, '<td valign="top">You''ve pushed the contrast too much. Too harsh, with blown out highlights (er, shadows). And the composition isn''t particularly interesting.</td>', 'You''ve pushed the contrast too much. Too harsh, with blown out highlights (er, shadows). And the composition isn''t particularly interesting.', '2008-04-20 19:19:15.000000', NULL, 1),
(4650125, 667650, 62249, '<td valign="top">Composition needs work. Zebras are interesting, but shot overall is a jumble of images. Pick one thing and fill the frame with it.</td>', 'Composition needs work. Zebras are interesting, but shot overall is a jumble of images. Pick one thing and fill the frame with it.', '2008-04-20 19:23:44.000000', NULL, 1),
(4650127, 669677, 62249, '<td valign="top">Pay attention to the interaction between foreground and background. Looks like the branches are growing out of the person''s head.</td>', 'Pay attention to the interaction between foreground and background. Looks like the branches are growing out of the person''s head.', '2008-04-20 19:25:30.000000', NULL, 1),
(4650128, 668697, 62249, '<td valign="top">There''s no real subject here. Shot needs something for viewers to focus on.</td>', 'There''s no real subject here. Shot needs something for viewers to focus on.', '2008-04-20 19:26:20.000000', NULL, 1),
(4650133, 669691, 62249, '<td valign="top">Crop off the lower portion of the shot. It doesn''t contain anything interesting. Fill more of the frame with the car and the colorful items in the upper portion.</td>', 'Crop off the lower portion of the shot. It doesn''t contain anything interesting. Fill more of the frame with the car and the colorful items in the upper portion.', '2008-04-20 19:27:40.000000', NULL, 1),
(4650138, 668986, 62249, '<td valign="top">Cute title but too much distracting stuff in lower portion of photo.</td>', 'Cute title but too much distracting stuff in lower portion of photo.', '2008-04-20 19:29:01.000000', NULL, 1),
(4650147, 669521, 62249, '<td valign="top">This is just a visual jumble. Pick one thing and make it clearly the subject of the photo.</td>', 'This is just a visual jumble. Pick one thing and make it clearly the subject of the photo.', '2008-04-20 19:31:23.000000', NULL, 1),
(4650159, 668482, 62249, '<td valign="top">Not a great subject for this challenge. Seeing the dog''s fur as black instead of white just isn''t too interesting, nor is the grass. The end result just looks like splotches of dar &amp; light without any real focal point.</td>', 'Not a great subject for this challenge. Seeing the dog''s fur as black instead of white just isn''t too interesting, nor is the grass. The end result just looks like splotches of dar & light without any real focal point.', '2008-04-20 19:36:15.000000', NULL, 1),
(4650164, 669950, 62249, '<td valign="top">Highlights (that is, shadows in the original) don''t have enough detail.</td>', 'Highlights (that is, shadows in the original) don''t have enough detail.', '2008-04-20 19:38:23.000000', NULL, 1),
(4650167, 669842, 62249, '<td valign="top">Gorgeous! This is very well done. Good tonal range. Interesting curves.</td>', 'Gorgeous! This is very well done. Good tonal range. Interesting curves.', '2008-04-20 19:40:01.000000', NULL, 1),
(4650169, 668338, 62249, '<td valign="top">Wow, this is lovely. Great tones and nice color in the flower in the right. Like how the delicate "veins" look.</td>', 'Wow, this is lovely. Great tones and nice color in the flower in the right. Like how the delicate "veins" look.', '2008-04-20 19:40:18.000000', NULL, 1),
(4650170, 669020, 62249, '<td valign="top">Very cool reflection of the photographer in the eyes. Great shot.</td>', 'Very cool reflection of the photographer in the eyes. Great shot.', '2008-04-20 19:41:28.000000', NULL, 1),
(4650172, 667793, 62249, '<td valign="top">Wings are BEAUTIFUL. Quite magical looking, with great detail. 10.</td>', 'Wings are BEAUTIFUL. Quite magical looking, with great detail. 10.', '2008-04-20 19:42:50.000000', NULL, 1),
