(4650557, 669791, 88054, '<td valign="top">Strange as it my be...I love the "white shadow". Nicely done.</td>', 'Strange as it my be...I love the "white shadow". Nicely done.', '2008-04-21 00:23:57.000000', NULL, 1),
(4650558, 669951, 88054, '<td valign="top">The flag and rooftop are slightly blown out. The sky is awesome. Still way above average.</td>', 'The flag and rooftop are slightly blown out. The sky is awesome. Still way above average.', '2008-04-21 00:25:02.000000', NULL, 1),
(4650559, 668697, 88054, '<td valign="top">Nice.</td>', 'Nice.', '2008-04-21 00:25:21.000000', NULL, 1),
(4650563, 669842, 88054, '<td valign="top">This is one of my top ten. What a great study of contrast. There is even a slight texture in the skin. Interesting crop...Very nice.</td>', 'This is one of my top ten. What a great study of contrast. There is even a slight texture in the skin. Interesting crop...Very nice.', '2008-04-21 00:28:16.000000', NULL, 1),
(4650564, 669269, 88054, '<td valign="top">Wow. That''s awesome. Easily a top ten for me.</td>', 'Wow. That''s awesome. Easily a top ten for me.', '2008-04-21 00:29:17.000000', NULL, 1),
(4650565, 670006, 88054, '<td valign="top">great shot. This should do very well.</td>', 'great shot. This should do very well.', '2008-04-21 00:30:05.000000', NULL, 1),
(4650566, 669854, 88054, '<td valign="top">Love the contrast and perspective. Would prefer to see just a tiny bit more of the tractor by taking a step or two to the left. I also would like to see the whole tire on the right rather than cropping part of it out. The sky is awesome. Still a top twenty finish from me. Great photo.</td>', 'Love the contrast and perspective. Would prefer to see just a tiny bit more of the tractor by taking a step or two to the left. I also would like to see the whole tire on the right rather than cropping part of it out. The sky is awesome. Still a top twenty finish from me. Great photo.', '2008-04-21 00:35:47.000000', NULL, 1),
(4650572, 669728, 88054, '<td valign="top">Not sure why but this looks a tad blurry to me. Probably just me.</td>', 'Not sure why but this looks a tad blurry to me. Probably just me.', '2008-04-21 00:37:17.000000', NULL, 1),
(4650576, 667802, 88054, '<td valign="top">Lovely. The only improvement I can think of would be if the birds head was turned to the right to give us a profile. Very Nice.</td>', 'Lovely. The only improvement I can think of would be if the birds head was turned to the right to give us a profile. Very Nice.', '2008-04-21 00:39:09.000000', NULL, 1),
(4650577, 669953, 88054, '<td valign="top">Now that''s cool.</td>', 'Now that''s cool.', '2008-04-21 00:39:29.000000', NULL, 1),
(4650578, 669839, 88054, '<td valign="top">I find this challenge very difficult to score. There are so many interesting shots. I love the contrast with the sky. after all the voting...This is one of my top three. Good luck.</td>', 'I find this challenge very difficult to score. There are so many interesting shots. I love the contrast with the sky. after all the voting...This is one of my top three. Good luck.', '2008-04-21 00:41:59.000000', NULL, 1),
(4650580, 668568, 88054, '<td valign="top">That''s awesome. I would have liked to see more of the horses feet though.</td>', 'That''s awesome. I would have liked to see more of the horses feet though.', '2008-04-21 00:43:06.000000', NULL, 1),
(4650582, 669883, 88054, '<td valign="top">This is a great photo. It certainly looks enchanted. Easily a top ten from me.</td>', 'This is a great photo. It certainly looks enchanted. Easily a top ten from me.', '2008-04-21 00:44:29.000000', NULL, 1),
