(4650590, 670047, 88054, '<td valign="top">The reflection in the window is very distracting.</td>', 'The reflection in the window is very distracting.', '2008-04-21 00:47:44.000000', NULL, 1),
(4650591, 668041, 88054, '<td valign="top">Lacks color. Too close.</td>', 'Lacks color. Too close.', '2008-04-21 00:48:50.000000', NULL, 1),
