(4651707, 669546, 14476, '<td valign="top">Gee, that looks familiar.  Nice angle on "the bridge."</td>', 'Gee, that looks familiar.  Nice angle on "the bridge."', '2008-04-21 14:37:32.000000', NULL, 1),
(4651868, 669529, 89341, '<td valign="top">I don''t know if you were going for a grainy shot but if not you can remove a lot of the grain with the despeckle filter</td>', 'I don''t know if you were going for a grainy shot but if not you can remove a lot of the grain with the despeckle filter', '2008-04-21 16:23:27.000000', NULL, 1),
