(4652283, 668710, 33769, '<td valign="top">majestic-and beautiful and amazing ! :)<a href="//www.dpchallenge.com/image.php?IMAGE_ID=669592" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/30000-34999/33769/120/669592.gif'', strrpos(''//images.dpchallenge.com/images_portfolio/30000-34999/33769/120/669592.gif'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/30000-34999/33769/120/669592.gif"/></a></td>', 'majestic-and beautiful and amazing ! :)', '2008-04-21 21:01:56.000000', NULL, 1),
(4652285, 669791, 33769, '<td valign="top">Very nice- I like how you obviously took the time to figure out what color would make brown :) *I know this from experimenting with lots of negatives myself!* :)  this photograph makes a great negative image! :) *two thumbs up* :) beautiful shapes/composition, and light/dark spots! :) *one of my faves* :)<a href="//www.dpchallenge.com/image.php?IMAGE_ID=669592" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/30000-34999/33769/120/669592.gif'', strrpos(''//images.dpchallenge.com/images_portfolio/30000-34999/33769/120/669592.gif'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/30000-34999/33769/120/669592.gif"/></a></td>', 'Very nice- I like how you obviously took the time to figure out what color would make brown :) *I know this from experimenting with lots of negatives myself!* :)  this photograph makes a great negative image! :) *two thumbs up* :) beautiful shapes/composition, and light/dark spots! :) *one of my faves* :)', '2008-04-21 21:02:06.000000', NULL, 1),
(4652286, 669808, 33769, '<td valign="top">really great idea! :) it almost does look like a x-ray :) that darn mascara tube on the edge told me how you did it tho ;) - i''m guessing you laid them ontop of a purse ? :) very original idea! very inspirational :) I gave this one a 10 because its simple, and creative :) I''m sure this will finish high! :) <a href="//www.dpchallenge.com/image.php?IMAGE_ID=669592" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/30000-34999/33769/120/669592.gif'', strrpos(''//images.dpchallenge.com/images_portfolio/30000-34999/33769/120/669592.gif'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/30000-34999/33769/120/669592.gif"/></a></td>', 'really great idea! :) it almost does look like a x-ray :) that darn mascara tube on the edge told me how you did it tho ;) - i''m guessing you laid them ontop of a purse ? :) very original idea! very inspirational :) I gave this one a 10 because its simple, and creative :) I''m sure this will finish high! :) ', '2008-04-21 21:02:15.000000', NULL, 1),
(4652304, 669594, 39427, '<td valign="top">love it. fav''d + 10</td>', 'love it. fav''d + 10', '2008-04-21 21:20:46.000000', NULL, 1),
(4652345, 668120, 9462, '<td valign="top">A gardeners flag!<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=670652" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/5000-9999/9462/120/670652.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/5000-9999/9462/120/670652.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/5000-9999/9462/120/670652.jpg"/></a></td>', 'A gardeners flag!', '2008-04-21 22:07:02.000000', NULL, 1),
(4652346, 669828, 9462, '<td valign="top">The perfect backdrop for a Haiku.</td>', 'The perfect backdrop for a Haiku.', '2008-04-21 22:07:33.000000', NULL, 1),
(4652347, 668976, 9462, '<td valign="top">The only way out is to journey within</td>', 'The only way out is to journey within', '2008-04-21 22:08:47.000000', NULL, 1),
(4652348, 669805, 9462, '<td valign="top">Music to my eyes</td>', 'Music to my eyes', '2008-04-21 22:09:17.000000', NULL, 1),
(4652496, 669838, 88136, '<td valign="top">trippy</td>', 'trippy', '2008-04-22 00:05:17.000000', NULL, 1),
(4652652, 670042, 91776, '<td valign="top">Great sense of dimensions...</td>', 'Great sense of dimensions...', '2008-04-22 02:07:54.000000', NULL, 1),
(4652726, 669418, 30982, '<td valign="top">Way cool!  Needs ghostly people wandering along that first balcony...</td>', 'Way cool!  Needs ghostly people wandering along that first balcony...', '2008-04-22 05:43:46.000000', NULL, 1),
(4652727, 669365, 30982, '<td valign="top">Classic composition that works very well in negative - better, I suspect, than the positive version.</td>', 'Classic composition that works very well in negative - better, I suspect, than the positive version.', '2008-04-22 05:44:12.000000', NULL, 1),
(4652728, 669135, 30982, '<td valign="top">Very good use of harsh glare and shadow - those things work well in negative.</td>', 'Very good use of harsh glare and shadow - those things work well in negative.', '2008-04-22 05:44:47.000000', NULL, 1),
(4652731, 668517, 30982, '<td valign="top">I very much like the sepia negative approach for this - quite fitting to the photograph.  I also like the foreground tree and the one it frames - they seem to be the watchmen over the fields.</td>', 'I very much like the sepia negative approach for this - quite fitting to the photograph.  I also like the foreground tree and the one it frames - they seem to be the watchmen over the fields.', '2008-04-22 05:51:47.000000', NULL, 1),
(4652732, 667443, 30982, '<td valign="top">Very nice use of natural framing and great subjects for this challenge!</td>', 'Very nice use of natural framing and great subjects for this challenge!', '2008-04-22 05:52:24.000000', NULL, 1),
(4652733, 668690, 30982, '<td valign="top">The color tones in negative are excellent!  Makes for a very intriguing image.</td>', 'The color tones in negative are excellent!  Makes for a very intriguing image.', '2008-04-22 05:52:45.000000', NULL, 1),
(4652734, 669848, 30982, '<td valign="top">Quite busy, and delightfully so!  Really a fun shot in negative.</td>', 'Quite busy, and delightfully so!  Really a fun shot in negative.', '2008-04-22 05:53:31.000000', NULL, 1),
(4652735, 668710, 30982, '<td valign="top">Awesome shot to start with - nifty in reverse mode.  Really highlights the massiveness of the place well.</td>', 'Awesome shot to start with - nifty in reverse mode.  Really highlights the massiveness of the place well.', '2008-04-22 05:54:08.000000', NULL, 1),
(4652736, 667832, 30982, '<td valign="top">Gorgeous with excellent detail.</td>', 'Gorgeous with excellent detail.', '2008-04-22 05:54:23.000000', NULL, 1),
(4652738, 669829, 30982, '<td valign="top">I suspect the colors of the original were played with a touch to get that lovely red sky, but the image works well this way - very powerful geometric shapes, well structured in the composition.  I like the reflected buildings.</td>', 'I suspect the colors of the original were played with a touch to get that lovely red sky, but the image works well this way - very powerful geometric shapes, well structured in the composition.  I like the reflected buildings.', '2008-04-22 05:55:14.000000', NULL, 1),
(4652740, 669452, 30982, '<td valign="top">A neat play on "photo finish" and I quite like how it looks in negative.</td>', 'A neat play on "photo finish" and I quite like how it looks in negative.', '2008-04-22 05:55:39.000000', NULL, 1),
(4652741, 669742, 30982, '<td valign="top">The negative really brings out the delicate nature of the stamens (I think they are) that might otherwise be lost in the positive.</td>', 'The negative really brings out the delicate nature of the stamens (I think they are) that might otherwise be lost in the positive.', '2008-04-22 05:56:17.000000', NULL, 1),
(4652743, 669011, 30982, '<td valign="top">Negative and upside down!  Nice combo!</td>', 'Negative and upside down!  Nice combo!', '2008-04-22 05:56:31.000000', NULL, 1),
(4652744, 669282, 30982, '<td valign="top">Normally I''d say that figurines and such aren''t good choices for challenges, but this one works exceptionally well in my opinion.  The richness of the painted horse is lovely in negative.</td>', 'Normally I''d say that figurines and such aren''t good choices for challenges, but this one works exceptionally well in my opinion.  The richness of the painted horse is lovely in negative.', '2008-04-22 05:57:12.000000', NULL, 1),
(4652746, 669436, 30982, '<td valign="top">Probably a somewhat mundane scene in positive (though well composed - don''t get me wrong) but it''s really quite intriguing in negative.  I like this.</td>', 'Probably a somewhat mundane scene in positive (though well composed - don''t get me wrong) but it''s really quite intriguing in negative.  I like this.', '2008-04-22 05:58:44.000000', NULL, 1),
(4652747, 669828, 30982, '<td valign="top">Wonderfully serene.</td>', 'Wonderfully serene.', '2008-04-22 05:58:57.000000', NULL, 1),
(4652748, 669800, 30982, '<td valign="top">Very intriguing layers to this - almost looks painted in parts.</td>', 'Very intriguing layers to this - almost looks painted in parts.', '2008-04-22 05:59:21.000000', NULL, 1),
(4652752, 669809, 30982, '<td valign="top">Good combination of detail/blur/DOF with very good supporting bokeh, and I love that wee bit of spider web.</td>', 'Good combination of detail/blur/DOF with very good supporting bokeh, and I love that wee bit of spider web.', '2008-04-22 06:01:47.000000', NULL, 1),
