INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4655763, 668597, 67152, '<td valign="top">an interesting effect, getting the sky to look dark and gloomy in the negative.  i just wonder how this shot would look if the lighthouse was not centered in the image.  i think by placing it dead center, it creates a rather static feel.  by placing it at the left third, we could get the impression that the light is ''looking out'' into the abyss.  more negative space and that cool sky would have probably boosted the score a bit.</td>', 'an interesting effect, getting the sky to look dark and gloomy in the negative.  i just wonder how this shot would look if the lighthouse was not centered in the image.  i think by placing it dead center, it creates a rather static feel.  by placing it at the left third, we could get the impression that the light is ''looking out'' into the abyss.  more negative space and that cool sky would have probably boosted the score a bit.', '2008-04-23 14:59:57.000000', NULL, 0),
(4655797, 667745, 39349, '<td valign="top">Tim,<br/> <br/>VERY creative work here. Congrats on another blue for you!<br/> <br/>Steve<br/></td>', 'Tim, VERY creative work here. Congrats on another blue for you! Steve', '2008-04-23 15:31:40.000000', NULL, 0),
